resources.afterResponseScript:
insomnia.test('HTTP 200', () => insomnia.expect(insomnia.response.code).to.eql(200));
if (insomnia.response.code === 200) {
  const data = insomnia.response.json();
  if (data.rol !== 'rol_admin') throw new Error('Esta cuenta no pertenece al rol admin; revisa sus credenciales');
  insomnia.environment.set("token_admin", data.token);
}

